# Order Service: reacts to PaymentResult, emits next steps
def on_payment_result(evt):
    if evt['status'] == 'CAPTURED':
        publish('orders', {
            'type': 'OrderConfirmed',
            'order_id': evt['order_id']
        })
    else:
        # Compensating action: payment failed, release the order
        publish('orders', {
            'type': 'OrderCancelled',
            'order_id': evt['order_id'],
            'reason': 'payment_failed'
        })

# Inventory Service: reacts to OrderConfirmed
def on_order_confirmed(evt):
    try:
        commit_reservation(evt['order_id'])
    except OutOfStock:
        # Compensate: trigger refund + cancellation
        publish('orders', {
            'type': 'OrderCancelled',
            'order_id': evt['order_id'],
            'reason': 'out_of_stock'
        })
        publish('payments', {
            'type': 'RefundRequested',
            'order_id': evt['order_id']
        })

